#include <cstdio>
#include <cstring>

#include "java/lang/Math.h"
#include "vsdk/toolkit/common/color/ColorRgb.h"
#include "vsdk/toolkit/io/image/ImagePersistenceRgbe.h"
#include "vsdk/toolkit/media/RGBImageFloatUncompressed.h"

void
ImagePersistenceRgbe::writeHeader(java::OutputStream &os, int width, int height) {
    char header[256];
    const int length = std::snprintf(
        header,
        sizeof(header),
        "#?RADIANCE\n"
        "# Image generated by VitralSDK (https://github.com/OscarChavarro/vitral)\n"
        "FORMAT=32-bit_rle_rgbe\n"
        "\n"
        "-Y %d +X %d\n",
        height,
        width);
    writeBytes(os, reinterpret_cast<const unsigned char *>(header), length);
}

/**
Converts a color to RGBE: the mantissas share the exponent of the largest
component. Colors whose largest component is at most 1e-32 (black, or with
all components negative) are stored as zero, and so are negative components.
*/
void
ImagePersistenceRgbe::rgbToRgbe(unsigned char *rgbe, double r, double g, double b) {
    double d = r > g ? r : g;
    if ( b > d ) {
        d = b;
    }

    if ( !(d > 1e-32) ) {
        rgbe[RED] = 0;
        rgbe[GREEN] = 0;
        rgbe[BLUE] = 0;
        rgbe[EXPONENT] = 0;
        return;
    }

    // d = mantissa * 2^e, with mantissa in [0.5, 1); compared before adding
    // one, as the exponent of an infinite d is the largest int
    int e = java::Math::getExponent(d);
    if ( e >= 255 - EXPONENT_EXCESS ) {
        // Too large for the exponent byte: the brightest representable value
        rgbe[RED] = 255;
        rgbe[GREEN] = 255;
        rgbe[BLUE] = 255;
        rgbe[EXPONENT] = 255;
        return;
    }
    e++;
    const double mantissa = java::Math::scalb(d, -e);
    d = mantissa * 255.9999 / d;

    rgbe[RED] = r > 0.0 ? static_cast<unsigned char>(r * d) : 0;
    rgbe[GREEN] = g > 0.0 ? static_cast<unsigned char>(g * d) : 0;
    rgbe[BLUE] = b > 0.0 ? static_cast<unsigned char>(b * d) : 0;
    rgbe[EXPONENT] = static_cast<unsigned char>(e + EXPONENT_EXCESS);
}

/**
Inverse of rgbToRgbe, at the center of the interval of the mantissa
*/
double
ImagePersistenceRgbe::rgbeComponentToDouble(int mantissa, int exponent) {
    if ( exponent == 0 ) {
        return 0.0;
    }
    return (static_cast<double>(mantissa) + 0.5) * java::Math::scalb(1.0, exponent - (EXPONENT_EXCESS + 8));
}

/**
Writes a scanline of RGBE pixels: run length encoded by component when its
width allows it, flat otherwise
*/
void
ImagePersistenceRgbe::writeScanline(java::OutputStream &os, const unsigned char *scanline, int width) {
    if ( width < MINIMUM_ENCODED_SCANLINE_LENGTH || width > MAXIMUM_ENCODED_SCANLINE_LENGTH ) {
        writeBytes(os, scanline, BYTES_PER_PIXEL * width);
        return;
    }

    // A component takes at most 2 bytes per pixel plus one: each run (of at
    // least 2 pixels) takes 2 bytes, and each non-run one byte more than its
    // pixels, with at most one non-run more than runs
    unsigned char *encoded = new unsigned char[4 + BYTES_PER_PIXEL * (2 * width + 1)];
    int n = 0;

    // Magic header
    encoded[n++] = 2;
    encoded[n++] = 2;
    encoded[n++] = static_cast<unsigned char>(width >> 8);
    encoded[n++] = static_cast<unsigned char>(width & 255);

    // Components separately
    for ( int i = 0; i < BYTES_PER_PIXEL; i++ ) {
        int count = 0;
        for ( int j = 0; j < width; j += count ) {
            // Find next run
            int begin;
            for ( begin = j; begin < width; begin += count ) {
                for ( count = 1;
                      count < 127 && begin + count < width
                      && scanline[(begin + count) * BYTES_PER_PIXEL + i] == scanline[begin * BYTES_PER_PIXEL + i];
                      count++ ) {
                }
                if ( count >= MINIMUM_RUN_LENGTH ) {
                    // Long enough
                    break;
                }
            }

            if ( begin - j > 1 && begin - j < MINIMUM_RUN_LENGTH ) {
                int c2 = j + 1;
                while ( scanline[(c2++) * BYTES_PER_PIXEL + i] == scanline[j * BYTES_PER_PIXEL + i] ) {
                    if ( c2 == begin ) {
                        // Short run
                        encoded[n++] = static_cast<unsigned char>(128 + begin - j);
                        encoded[n++] = scanline[j * BYTES_PER_PIXEL + i];
                        j = begin;
                        break;
                    }
                }
            }
            while ( j < begin ) {
                // Non-run
                int c2 = begin - j;
                if ( c2 > 128 ) {
                    c2 = 128;
                }
                encoded[n++] = static_cast<unsigned char>(c2);
                while ( c2-- ) {
                    encoded[n++] = scanline[(j++) * BYTES_PER_PIXEL + i];
                }
            }
            if ( count >= MINIMUM_RUN_LENGTH ) {
                // Run
                encoded[n++] = static_cast<unsigned char>(128 + count);
                encoded[n++] = scanline[begin * BYTES_PER_PIXEL + i];
            } else {
                count = 0;
            }
        }
    }

    writeBytes(os, encoded, n);
    delete[] encoded;
}

bool
ImagePersistenceRgbe::exportRgbe(java::OutputStream &os, const RGBImageFloatUncompressed *image) {
    if ( image == nullptr || image->getXSize() <= 0 || image->getYSize() <= 0 ) {
        return false;
    }

    const int width = image->getXSize();
    const int height = image->getYSize();
    writeHeader(os, width, height);

    unsigned char *scanline = new unsigned char[BYTES_PER_PIXEL * width];
    for ( int y = 0; y < height; y++ ) {
        for ( int x = 0; x < width; x++ ) {
            const ColorRgb color = image->getPixel(x, y);
            rgbToRgbe(&scanline[x * BYTES_PER_PIXEL], color.getR(), color.getG(), color.getB());
        }
        writeScanline(os, scanline, width);
    }
    delete[] scanline;
    return true;
}

bool
ImagePersistenceRgbe::readFully(java::InputStream &is, unsigned char *buffer, int length) {
    int offset = 0;
    while ( offset < length ) {
        const int numRead = is.read(buffer, offset, length - offset);
        if ( numRead <= 0 ) {
            return false;
        }
        offset += numRead;
    }
    return true;
}

/**
Reads a header line without its end of line. False at the end of the stream
or for a line longer than the capacity of the buffer.
*/
bool
ImagePersistenceRgbe::readHeaderLine(java::InputStream &is, char *line, int capacity) {
    int length = 0;
    while ( true ) {
        const int c = is.read();
        if ( c < 0 ) {
            return false;
        }
        if ( c == '\n' ) {
            break;
        }
        if ( length >= capacity - 1 ) {
            return false;
        }
        line[length++] = static_cast<char>(c);
    }
    line[length] = '\0';
    return true;
}

bool
ImagePersistenceRgbe::readHeader(java::InputStream &is, int *width, int *height) {
    char line[1024];
    if ( !readHeaderLine(is, line, sizeof(line)) || std::strncmp(line, "#?", 2) != 0 ) {
        return false;
    }

    // Variables up to the empty line
    while ( true ) {
        if ( !readHeaderLine(is, line, sizeof(line)) ) {
            return false;
        }
        if ( line[0] == '\0' ) {
            break;
        }
        if ( std::strncmp(line, "FORMAT=", 7) == 0 && std::strcmp(line + 7, "32-bit_rle_rgbe") != 0 ) {
            return false;
        }
    }

    // Resolution
    if ( !readHeaderLine(is, line, sizeof(line)) ) {
        return false;
    }
    char trailing;
    if ( std::sscanf(line, "-Y %d +X %d%c", height, width, &trailing) != 2 ) {
        return false;
    }
    return *width > 0 && *height > 0;
}

/**
Reads the rest of a flat scanline, whose first pixel is already in
`scanline`. As in Radiance, a pixel with r = g = b = 1 after the first one is
an "old" run length encoded repeat count of the previous pixel (shifted by 8
bits for each consecutive count).
*/
bool
ImagePersistenceRgbe::readOldScanline(java::InputStream &is, unsigned char *scanline, int width) {
    int shift = 0;
    int x = 1;
    while ( x < width ) {
        unsigned char *pixel = &scanline[x * BYTES_PER_PIXEL];
        if ( !readFully(is, pixel, BYTES_PER_PIXEL) ) {
            return false;
        }
        if ( pixel[RED] == 1 && pixel[GREEN] == 1 && pixel[BLUE] == 1 ) {
            int repeat = static_cast<int>(pixel[EXPONENT]) << shift;
            if ( repeat > width - x ) {
                return false;
            }
            for ( ; repeat > 0; repeat-- ) {
                std::memcpy(&scanline[x * BYTES_PER_PIXEL], &scanline[(x - 1) * BYTES_PER_PIXEL], BYTES_PER_PIXEL);
                x++;
            }
            shift += 8;
        } else {
            shift = 0;
            x++;
        }
    }
    return true;
}

bool
ImagePersistenceRgbe::readScanline(java::InputStream &is, unsigned char *scanline, int width) {
    if ( width < MINIMUM_ENCODED_SCANLINE_LENGTH || width > MAXIMUM_ENCODED_SCANLINE_LENGTH ) {
        if ( !readFully(is, scanline, BYTES_PER_PIXEL) ) {
            return false;
        }
        return readOldScanline(is, scanline, width);
    }

    unsigned char start[BYTES_PER_PIXEL];
    if ( !readFully(is, start, BYTES_PER_PIXEL) ) {
        return false;
    }
    if ( start[0] != 2 || start[1] != 2 || (start[2] & 0x80) != 0 ) {
        // Not run length encoded by component: a flat (or old) scanline
        std::memcpy(scanline, start, BYTES_PER_PIXEL);
        return readOldScanline(is, scanline, width);
    }
    if ( ((static_cast<int>(start[2]) << 8) | start[3]) != width ) {
        return false;
    }

    for ( int i = 0; i < BYTES_PER_PIXEL; i++ ) {
        int x = 0;
        while ( x < width ) {
            const int code = is.read();
            if ( code <= 0 ) {
                return false;
            }
            if ( code > 128 ) {
                // Run
                const int count = code - 128;
                const int value = is.read();
                if ( value < 0 || count > width - x ) {
                    return false;
                }
                for ( int k = 0; k < count; k++ ) {
                    scanline[(x++) * BYTES_PER_PIXEL + i] = static_cast<unsigned char>(value);
                }
            } else {
                // Non-run
                if ( code > width - x ) {
                    return false;
                }
                for ( int k = 0; k < code; k++ ) {
                    const int value = is.read();
                    if ( value < 0 ) {
                        return false;
                    }
                    scanline[(x++) * BYTES_PER_PIXEL + i] = static_cast<unsigned char>(value);
                }
            }
        }
    }
    return true;
}

RGBImageFloatUncompressed *
ImagePersistenceRgbe::importRgbe(java::InputStream &is) {
    int width = 0;
    int height = 0;
    if ( !readHeader(is, &width, &height) ) {
        return nullptr;
    }

    RGBImageFloatUncompressed *image = new RGBImageFloatUncompressed();
    if ( !image->initNoFill(width, height) ) {
        delete image;
        return nullptr;
    }

    unsigned char *scanline = new unsigned char[BYTES_PER_PIXEL * width];
    for ( int y = 0; y < height; y++ ) {
        if ( !readScanline(is, scanline, width) ) {
            delete[] scanline;
            delete image;
            return nullptr;
        }
        for ( int x = 0; x < width; x++ ) {
            const unsigned char *pixel = &scanline[x * BYTES_PER_PIXEL];
            const int exponent = pixel[EXPONENT];
            image->putPixel(
                x,
                y,
                rgbeComponentToDouble(pixel[RED], exponent),
                rgbeComponentToDouble(pixel[GREEN], exponent),
                rgbeComponentToDouble(pixel[BLUE], exponent));
        }
    }
    delete[] scanline;
    return image;
}
